//! Live native validity views share actual current control state.
use super::*;
fn start(source:&str)->(Document,Forms,Page){let mut d=crate::html::parse("<body><form id=form><input id=input name=q required><textarea id=area required></textarea><select id=select required><option value=''>Pick</option><option value=ready>Ready</option></select><button id=button>Submit</button><input id=check type=checkbox required disabled><input id=radio type=radio name=r required disabled><input id=peer type=radio name=r></form><input id=number type=number><datalist><input id=listed required></datalist></body>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://candidate-validity.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);let out=p.start(&mut d,&mut f,&[Script{node:0,label:"Live native validity".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",p.report());(d,f,p)}
#[test]
fn candidate_validity_canonical_identity_current_required_and_custom_flags(){
 start("var ids=['input','area','select','button'],classes=[HTMLInputElement,HTMLTextAreaElement,HTMLSelectElement,HTMLButtonElement];for(var i=0;i<ids.length;i++){var x=document.getElementById(ids[i]),a=Object.getOwnPropertyDescriptor(classes[i].prototype,'validity'),v=x.validity;if(!a||!a.enumerable||!a.configurable||a.set!==undefined||a.get.name!=='get validity'||a.get.length!==0||Object.hasOwn(x,'validity')||!(v instanceof ValidityState)||v!==x.validity||v!==a.get.call(x))throw 'canonical live identity';if(v.valueMissing!==(i!==3)||v.valid!==(i===3)||v.customError)throw 'required state';for(var key of ['typeMismatch','patternMismatch','tooLong','tooShort','rangeUnderflow','rangeOverflow','stepMismatch','badInput'])if(v[key]!==false)throw 'inapplicable constraint';x.setCustomValidity('Custom');if(!v.customError||v.valid||x.validity!==v)throw 'live custom';x.disabled=true;if(!v.customError||v.valid||x.validationMessage!==''||!x.checkValidity())throw 'barred custom remains invalid';x.disabled=false;x.setCustomValidity('');if(v.customError)throw 'clear custom';}document.getElementById('input').value='Ready';document.getElementById('area').value='Body';document.getElementById('select').value='ready';for(var id of ids)if(!document.getElementById(id).validity.valid)throw 'live repaired';");
}
#[test]
fn candidate_validity_flags_do_not_confuse_barred_eligibility_with_constraints(){
 start("var x=document.getElementById('input'),a=document.getElementById('area'),s=document.getElementById('select'),c=document.getElementById('check'),r=document.getElementById('radio'),peer=document.getElementById('peer');x.disabled=true;a.readOnly=true;s.disabled=true;if(x.validity.valueMissing||a.validity.valueMissing||!s.validity.valueMissing||!c.validity.valueMissing||!r.validity.valueMissing||x.willValidate||s.willValidate||c.willValidate||r.willValidate)throw 'barred versus missing';peer.checked=true;if(r.validity.valueMissing||!r.validity.valid)throw 'current radio group';x.disabled=false;x.readOnly=true;if(x.validity.valueMissing)throw 'readonly mutable';x.readOnly=false;if(!x.validity.valueMissing)throw 'restored required';");
}

#[test]
fn candidate_validity_readonly_brands_and_saved_author_shadows(){
 start("var ids=['input','area','select','button'],classes=[HTMLInputElement,HTMLTextAreaElement,HTMLSelectElement,HTMLButtonElement],flag=Object.getOwnPropertyDescriptor(ValidityState.prototype,'customError');for(var i=0;i<ids.length;i++){var x=document.getElementById(ids[i]),a=Object.getOwnPropertyDescriptor(classes[i].prototype,'validity'),v=x.validity;for(var bad of [{},Object.create(classes[i].prototype),v,document.getElementById(ids[(i+1)%4])]){var denied=false;try{a.get.call(bad);}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'concrete validity brand';}for(var bad of [{},Object.create(ValidityState.prototype),x]){var denied=false;try{flag.get.call(bad);}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'genuine validity brand';}x.validity='author';v.customError=true;if(x.validity!==v||v.customError||Object.hasOwn(x,'validity')||Object.hasOwn(v,'customError'))throw 'readonly assignment';var denied=false;try{(function(){'use strict';x.validity='author';})();}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'strict readonly';Object.defineProperty(x,'validity',{value:'own',configurable:true});x.setCustomValidity('Stored');if(x.validity!=='own'||a.get.call(x)!==v||!flag.get.call(v))throw 'own shadow';delete x.validity;Object.defineProperty(v,'customError',{value:'own',configurable:true});x.setCustomValidity('');if(v.customError!=='own'||flag.get.call(v)!==false)throw 'flag shadow independence';delete v.customError;if(v.customError||x.validity!==v)throw 'shadow recovery';}var denied=false;try{new ValidityState();}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'illegal constructor';");
}
#[test]
fn candidate_validity_unsupported_constraints_refuse_without_hiding_known_custom_error(){
 start("var x=document.getElementById('input'),v=x.validity;x.setAttribute('pattern','[A-Z]+');if(v.valueMissing!==true||v.customError!==false)throw 'independent known flags';var denied=false;try{var valid=v.valid;}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'pattern backend refusal';x.setCustomValidity('Known invalid');if(!v.customError||v.valid!==false)throw 'known custom invalid';x.setCustomValidity('');x.removeAttribute('pattern');if(v.valid!==false||!v.valueMissing)throw 'supported recovery';var number=document.getElementById('number'),numeric=number.validity;if(!(numeric instanceof ValidityState)||numeric.customError)throw 'unsupported still genuine view';denied=false;try{var missing=numeric.valueMissing;}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'numeric backend refusal';number.setCustomValidity('Numeric custom');if(!numeric.customError||numeric.valid!==false)throw 'numeric known invalid';var area=document.getElementById('area'),av=area.validity;area.setAttribute('maxlength','3');if(!av.valueMissing)throw 'length independent missing';denied=false;try{var tooLong=av.tooLong;}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'length backend refusal';area.removeAttribute('maxlength');if(av.tooLong)throw 'length recovery';");
}
#[test]
fn candidate_validity_live_reset_and_native_adoption_refusal(){
 start("var x=document.getElementById('input'),v=x.validity,form=document.getElementById('form');x.value='Edited';x.setCustomValidity('Persistent');form.reset();if(x.validity!==v||!v.valueMissing||!v.customError||v.valid)throw 'live reset';var target=document.implementation.createHTMLDocument('target'),denied=false;try{target.adoptNode(x);}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied||x.ownerDocument!==document||x.parentNode!==form||x.validity!==v||!v.customError)throw 'adoption preserves state';x.setCustomValidity('');x.value='Recovered';if(!v.valid||v.valueMissing||v.customError)throw 'lifecycle recovery';");
}
#[test]
fn candidate_validity_saved_child_canonical_roots_and_origin_refusal(){
 let(mut d,mut f,mut p)=start("var x=document.getElementById('input'),v=x.validity,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'validity').get,flag=Object.getOwnPropertyDescriptor(frame.contentWindow.ValidityState.prototype,'valueMissing').get;if(get.call(x)!==v||!flag.call(v))throw 'saved child canonical';var inert=document.implementation.createHTMLDocument('inert').createElement('input'),denied=false;try{get.call(inert);}catch(e){denied=e instanceof frame.contentWindow.DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'inert backend refusal';");let before=format!("{:?}",d.nodes);p.set_location(&crate::navigation::address("https://foreign-validity.test/",&crate::navigation::Location::home()).unwrap());for source in ["get.call(x);","flag.call(v);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://candidate-validity.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();p.runtime.execute("if(get.call(x)!==v||!flag.call(v))throw 'authority recovery';x.value='Ready';if(flag.call(v))throw 'live saved flag';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
#[test]
fn candidate_validity_read_refusals_and_allocation_free_reads_recover(){
 for mode in 0..3{let(mut d,mut f,mut p)=start("var x=document.getElementById('input'),v=x.validity;x.setCustomValidity('Stored');");p.state.rebuild(&d).unwrap();let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();let object=script_output_validity_state::handle(node_handle(node));let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.host_work=p.state.output_custom_errors.lookup_work()*4}assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_validity_call(object,"\0ValidityState.get.valid",&[]).is_err());assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits),before);let limit=p.state.retained_limit;p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_validity_call(object,"\0ValidityState.get.customError",&[]).unwrap(),Value::Bool(true)));p.state.retained_limit=limit;p.begin_job();p.runtime.execute("if(x.validity!==v||!v.customError||!v.valueMissing||v.valid)throw 'refusal recovery';x.setCustomValidity('');x.value='Ready';if(!v.valid)throw 'fresh valid recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();}
}
#[test]
fn candidate_validity_flags_do_not_dispatch_or_mask_each_other(){
 start("var x=document.getElementById('input'),v=x.validity,events=0;x.addEventListener('invalid',function(){events++;});x.setCustomValidity('Custom');if(!v.valueMissing||!v.customError||v.valid||events)throw 'independent flags';x.value='Ready';if(v.valueMissing||!v.customError||v.valid||events)throw 'required repaired only';x.setCustomValidity('');if(!v.valid||v.customError||events)throw 'custom repaired';var listed=document.getElementById('listed'),lv=listed.validity;if(listed.willValidate||lv.customError||!listed.checkValidity()||events)throw 'datalist barred candidate';var denied=false;try{var missing=lv.valueMissing;}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'datalist state backend refusal';listed.setCustomValidity('Listed');if(!lv.customError||lv.valid||!listed.checkValidity()||events)throw 'barred known custom flags';");
}

